import{_ as t,o,c as a,aa as i}from"./chunks/framework.BAs_AphD.js";const u=JSON.parse('{"title":"Welcome to Buildary.online","description":"","frontmatter":{"title":"Welcome to Buildary.online","wiki":"en:firstofall:start"},"headers":[],"relativePath":"en/firstofall/index.md","filePath":"en/firstofall/index.md","lastUpdated":1793088561000}'),n={name:"en/firstofall/index.md"};function r(l,e,s,d,p,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="welcome-to-buildary-online" tabindex="-1">Welcome to Buildary.online <a class="header-anchor" href="#welcome-to-buildary-online" aria-label="Permalink to &quot;Welcome to Buildary.online&quot;">​</a></h1><p>The Buildary.online application (hereinafter referred to as <strong>Buildary</strong>) is a modular application operated in Microsoft Azure cloud. Data is protected against unauthorized access, loss, or misuse, and it is guaranteed that it will not leave the territory of the European Union.</p><p>Thanks to its cloud-based architecture, information in the application is available to authorized persons anytime and anywhere an internet connection is available.</p><p>The application currently includes the following modules:</p><ul><li>Project Diary</li><li>Ticket Management</li><li>Performed Works</li></ul><p>The modules can operate independently or, ideally, work together.</p><p>To use the application, you need to register and then sign in. You can either use your email address and chosen password or sign in using an Azure AD account.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>After registering for the application, you have the option to have a <strong>Demo Project</strong> with sample data generated for all three modules <strong>the first time you sign in</strong>. We recommend taking advantage of this offer, as it is a completely free way to try out the application&#39;s functionality. The Demo Project will be automatically deleted by the system after one month.</p></div><p>For more detailed information on how to register for the application and how to proceed step by step, click the appropriate link in the sidebar.</p><h2 id="video-help" tabindex="-1">Video Help <a class="header-anchor" href="#video-help" aria-label="Permalink to &quot;Video Help&quot;">​</a></h2><p>For those who don&#39;t like reading Help documentation, we have prepared video explanations for the most important parts of the application. Each video covers a specific topic, and after watching them, you should be able to work with Buildary independently.</p><p>You can find the list of Help videos here: <a href="https://www.youtube.com/playlist?list=PL3uJDDr4spKHscqIIixyXe3JQgdJXZ0Gk" target="_blank" rel="noreferrer">https://www.youtube.com/playlist?list=PL3uJDDr4spKHscqIIixyXe3JQgdJXZ0Gk</a></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The current version of Buildary may contain some new features that are not covered in the videos. In such cases, you should refer to the Help documentation to find information about the relevant functionality.</p></div>',13)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
